# Generated by build.py from recipe.yml for recipe sftp-give-each-user-their-key. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
cmd /c 'ssh-keygen -q -t rsa -b 3072 -N "" -f host_key'
cmd /c 'ssh-keygen -q -t rsa -b 3072 -N "" -f deploy_a'
cmd /c 'ssh-keygen -q -t rsa -b 3072 -N "" -f deploy_a2'
cmd /c 'ssh-keygen -q -t rsa -b 3072 -N "" -f deploy_b'
cmd /c 'cat deploy_a.pub deploy_a2.pub > a_keys'
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', '--hostkey', 'host_key', '--authorized-keys', 'deploy-a:a_keys', '--authorized-keys', 'deploy-b:deploy_b.pub', 'sftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -S -k -u deploy-a: --key deploy_a --pubkey deploy_a.pub sftp://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
